```js
async function verifyQrEncodes(page, payload) {
  return page.evaluate(async (expected) => {
    const entries = performance.getEntriesByType("resource").map(e => e.name)
    const pick = pattern => entries.find(name => pattern.test(name))
    const qrUrl = pick(/qrcode_react\.js/)
    const reactUrl = pick(/deps\/react\.js/)
    const domUrl = pick(/deps\/react-dom_client\.js/)
    if (!qrUrl || !reactUrl || !domUrl) return { ok: false, reason: "module urls not found", entries: entries.length }
    const qr = await import(qrUrl)
    const react = await import(reactUrl)
    const dom = await import(domUrl)
    const React = react.default ?? react
    const createRoot = (dom.default ?? dom).createRoot
    const host = document.createElement("div")
    host.style.position = "fixed"; host.style.left = "-10000px"
    document.body.appendChild(host)
    const root = createRoot(host)
    root.render(React.createElement(qr.QRCodeSVG, { value: expected, size: 192, level: "M", "aria-label": "reference" }))
    const deadline = Date.now() + 4000
    let svg = null
    while (Date.now() < deadline && !svg) { await new Promise(r => setTimeout(r, 50)); svg = host.querySelector("svg") }
    const result = svg ? { ok: true, viewBox: svg.getAttribute("viewBox"), d: [...svg.querySelectorAll("path")].map(p => p.getAttribute("d")).join("|") } : { ok: false, reason: "reference svg not rendered" }
    root.unmount(); host.remove()
    return result
  }, payload)
}
```
